  app2.get("/api/branches/stats", requireAuth, requireManager, async (req, res) => {
    try {
      const { BranchModel: BranchModel2, OrderModel: OrderModel2, EmployeeModel: EmployeeModel2 } = await Promise.resolve().then(() => (init_schema(), schema_exports));
      const tenantId = getTenantIdFromRequest(req) || process.env.TENANT_ID;
      const dayStart = getSaudiStartOfDay();
      const dayEnd = getSaudiEndOfDay();
      const branches = await BranchModel2.find({ tenantId, isActive: { $in: [1, true] } }).lean();
      const statsArr = await Promise.all(branches.map(async (b) => {
        const branchId = b.id || b._id?.toString();
        const [todayOrders, allOrders, employees] = await Promise.all([
          OrderModel2.find({
            tenantId,
            branchId,
            status: { $nin: ["cancelled"] },
            createdAt: { $gte: dayStart, $lte: dayEnd }
          }).lean(),
          OrderModel2.find({
            tenantId,
            branchId,
            status: { $nin: ["cancelled"] }
          }).lean(),
          EmployeeModel2.countDocuments({ tenantId, branchId, isActive: true })
        ]);
        const todayRevenue = todayOrders.reduce((s, o) => s + (Number(o.totalAmount) || 0), 0);
        const totalRevenue = allOrders.reduce((s, o) => s + (Number(o.totalAmount) || 0), 0);
        return {
          branchId,
          todayOrders: todayOrders.length,
          todayRevenue: Math.round(todayRevenue * 100) / 100,
          totalOrders: allOrders.length,
          totalRevenue: Math.round(totalRevenue * 100) / 100,
          activeEmployees: employees,
          isOnline: b.isOnline !== false
        };
      }));
      res.json(statsArr);
    } catch (err) {
      console.error("branches/stats error:", err);
      res.status(500).json({ error: err.message });
    }
  });
